import { useMemo } from 'react';
import { useSelector } from 'react-redux';

function ExpensiveComponent() {
  const users = useSelector(state => state.users);

  // ✅ GOOD: This heavy calculation ONLY runs when 'users' actually changes!
  // If this component re-renders because 'theme' changed, this math is skipped.
  const sortedUsers = useMemo(() => {
    console.log('Running heavy sort algorithm...');
    return [...users].sort((a, b) => a.name.localeCompare(b.name));
  }, [users]);

  return <div>{sortedUsers.length} Users</div>;
}
